{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.UserMessageExpression",
  "description": "Expression variant of [`UserMessage`] for dynamic content.",
  "type": "object",
  "properties": {
    "content": {
      "description": "The message content expression.",
      "$ref": "functions.expression.WithExpression.agent.completions.message.RichContentExpression"
    },
    "name": {
      "description": "Optional name expression.",
      "anyOf": [
        {
          "$ref": "functions.expression.WithExpression.Nullable_string"
        },
        {
          "type": "null"
        }
      ]
    }
  },
  "required": [
    "content"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.RichContent",
  "description": "Rich content for user/assistant messages (supports multimodal input).",
  "anyOf": [
    {
      "description": "Plain text content.",
      "type": "string"
    },
    {
      "description": "Multi-part content (text, images, audio, video, files).",
      "type": "array",
      "items": {
        "$ref": "agent.completions.message.RichContentPart"
      }
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.RichContentPart",
  "description": "A part of rich content.",
  "oneOf": [
    {
      "description": "Text content.",
      "type": "object",
      "properties": {
        "text": {
          "type": "string"
        },
        "type": {
          "type": "string",
          "const": "text"
        }
      },
      "required": [
        "type",
        "text"
      ]
    },
    {
      "description": "An image URL.",
      "type": "object",
      "properties": {
        "image_url": {
          "$ref": "agent.completions.message.ImageUrl"
        },
        "type": {
          "type": "string",
          "const": "image_url"
        }
      },
      "required": [
        "type",
        "image_url"
      ]
    },
    {
      "description": "Audio input.",
      "type": "object",
      "properties": {
        "input_audio": {
          "$ref": "agent.completions.message.InputAudio"
        },
        "type": {
          "type": "string",
          "const": "input_audio"
        }
      },
      "required": [
        "type",
        "input_audio"
      ]
    },
    {
      "description": "Video input.",
      "type": "object",
      "properties": {
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        },
        "type": {
          "type": "string",
          "const": "input_video"
        }
      },
      "required": [
        "type",
        "video_url"
      ]
    },
    {
      "description": "A video URL.",
      "type": "object",
      "properties": {
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        },
        "type": {
          "type": "string",
          "const": "video_url"
        }
      },
      "required": [
        "type",
        "video_url"
      ]
    },
    {
      "description": "A file.",
      "type": "object",
      "properties": {
        "file": {
          "$ref": "agent.completions.message.File"
        },
        "type": {
          "type": "string",
          "const": "file"
        }
      },
      "required": [
        "type",
        "file"
      ]
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.MessageExpression",
  "description": "A message with expressions for dynamic content.\n\nThis is the expression variant of [`Message`] used in function definitions\nwhere message content can be computed from the function input at runtime.\nSupports both JMESPath and Starlark expressions.",
  "oneOf": [
    {
      "type": "object",
      "properties": {
        "role": {
          "type": "string",
          "const": "developer"
        }
      },
      "$ref": "agent.completions.message.DeveloperMessageExpression",
      "required": [
        "role"
      ]
    },
    {
      "type": "object",
      "properties": {
        "role": {
          "type": "string",
          "const": "system"
        }
      },
      "$ref": "agent.completions.message.SystemMessageExpression",
      "required": [
        "role"
      ]
    },
    {
      "type": "object",
      "properties": {
        "role": {
          "type": "string",
          "const": "user"
        }
      },
      "$ref": "agent.completions.message.UserMessageExpression",
      "required": [
        "role"
      ]
    },
    {
      "type": "object",
      "properties": {
        "role": {
          "type": "string",
          "const": "assistant"
        }
      },
      "$ref": "agent.completions.message.AssistantMessageExpression",
      "required": [
        "role"
      ]
    },
    {
      "type": "object",
      "properties": {
        "role": {
          "type": "string",
          "const": "tool"
        }
      },
      "$ref": "agent.completions.message.ToolMessageExpression",
      "required": [
        "role"
      ]
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.ToolMessageExpression",
  "description": "Expression variant of [`ToolMessage`] for dynamic content.",
  "type": "object",
  "properties": {
    "content": {
      "description": "The content expression.",
      "$ref": "functions.expression.WithExpression.agent.completions.message.RichContentExpression"
    },
    "tool_call_id": {
      "description": "The tool call ID expression.",
      "$ref": "functions.expression.WithExpression.string"
    }
  },
  "required": [
    "content",
    "tool_call_id"
  ]
}

